import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../main.dart';
import '../services/integrations.dart';
class SettingsScreen extends ConsumerWidget { const SettingsScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref) { final current = ref.watch(localeProvider); return Scaffold(appBar: AppBar(title: const Text('الإعدادات')), body: ListView(children: [ListTile(title: const Text('اللغة'), trailing: DropdownButton<Locale>(value: current, items: const [DropdownMenuItem(value: Locale('ar'), child: Text('العربية')), DropdownMenuItem(value: Locale('en'), child: Text('English'))], onChanged: (locale) { if (locale != null) ref.read(localeProvider.notifier).state = locale; })), const Divider(), ListTile(title: const Text('RevenueCat'), subtitle: Text(Integrations.revenueCatEnabled ? 'Configured' : 'Requires Credentials')), const ListTile(title: Text('Supabase'), subtitle: Text('Requires Credentials')), const ListTile(title: Text('Sentry'), subtitle: Text('Disabled')), const ListTile(title: Text('Firebase Analytics'), subtitle: Text('Disabled until Firebase configuration is added'))])); } }
